<div class="pricing-editor">
<section class="admin-page-head"><div><p class="admin-kicker">HERRAMIENTA DE PRECIOS</p><h1>Precio efectivo</h1><p>Consulta el total y los impuestos para una cantidad y fecha. Este cálculo no crea cotizaciones ni guarda ventas.</p></div><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/prices">Volver</a></section>
<form class="admin-panel admin-form" method="get" action="/admin/prices/calculate" data-admin-modal-get><div class="admin-form-grid"><label class="admin-field"><span>Sucursal</span><select name="branch_id" required><option value="">Selecciona</option><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $values['branch_id']===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Variante</span><select name="variant_id" required><option value="">Selecciona</option><?php foreach($variants as$v):?><option value="<?= e($v['id']) ?>" <?= $values['variant_id']===(int)$v['id']?'selected':'' ?>><?= e($v['product_name'].' · '.$v['sku']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Lista</span><select name="list_id" required><?php foreach($lists as$l):?><option value="<?= e($l['id']) ?>" <?= $values['list_id']===(int)$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Fecha</span><input type="date" name="date" required value="<?= e($values['date']) ?>"></label><label class="admin-field pricing-field-full"><span>Cantidad</span><input name="quantity" inputmode="decimal" required value="<?= e($values['quantity']) ?>"></label></div><div class="admin-head-actions"><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/prices">Cerrar</a><button class="admin-primary-button">Calcular</button></div></form>
<?php if($error!==null):?><div class="admin-alert admin-alert-error" role="alert"><?= e($error) ?></div><?php elseif($values['variant_id']&&$result===null):?><div class="admin-panel admin-empty"><strong>Sin precio configurado</strong><span>No existe un precio y tasa activos para ese alcance y fecha.</span></div><?php elseif($result!==null):?><section class="admin-panel pricing-result" aria-live="polite"><h2>Resultado del cálculo</h2><dl class="admin-definition-grid"><div><dt>Precio unitario</dt><dd>$<?= e($result['calculation']['unit_price']) ?> MXN</dd></div><div><dt>Origen</dt><dd><?= $result['price']['source']==='explicit'?'Precio explícito':'Regla general de lista' ?></dd></div><div><dt>Subtotal</dt><dd>$<?= e($result['calculation']['subtotal']) ?></dd></div><div><dt>Impuesto (<?= e($result['calculation']['tax_rate']) ?> %)</dt><dd>$<?= e($result['calculation']['tax']) ?></dd></div><div><dt>Total estimado</dt><dd><strong>$<?= e($result['calculation']['total']) ?> MXN</strong></dd></div><div><dt>Criterio</dt><dd><?= $result['calculation']['tax_included']?'Precio con impuesto incluido':'Precio antes de impuesto' ?></dd></div></dl></section><?php endif?>

